exercises.solution:
def kuantil(data, q):
    s = sorted(data)
    p = (len(s) - 1) * q
    lo = int(p)
    hi = min(lo + 1, len(s) - 1)
    return round(s[lo] + (s[hi] - s[lo]) * (p - lo), 4)

